package com.pethop.user;
import com.pethop.admin.AdminAuditService; import com.pethop.common.exception.ApiException; import com.pethop.common.response.PageResponse; import com.pethop.user.dto.*; import com.pethop.security.SecurityUser; import java.util.Locale; import java.util.UUID; import org.springframework.data.domain.*; import org.springframework.data.jpa.domain.Specification; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class AdminUserService{
 private final UserRepository users; private final AdminAuditService audit;
 public AdminUserService(UserRepository u,AdminAuditService a){users=u;audit=a;}
 @Transactional(readOnly=true) public PageResponse<AdminUserResponse> list(String search,int page,int size){Specification<User> spec=(root,q,cb)->{if(search==null||search.isBlank())return cb.conjunction();String x="%"+search.trim().toLowerCase(Locale.ROOT)+"%";return cb.or(cb.like(cb.lower(root.get("fullName")),x),cb.like(cb.lower(root.get("email")),x));};return PageResponse.from(users.findAll(spec,PageRequest.of(page,size,Sort.by(Sort.Direction.DESC,"createdAt"))),AdminUserResponse::from);}
 @Transactional(readOnly=true) public AdminUserResponse get(UUID id){return AdminUserResponse.from(find(id));}
 @Transactional public AdminUserResponse change(UUID id,SecurityUser actor,AdminUserActionRequest request){User target=users.findByIdForUpdate(id).orElseThrow(()->ApiException.notFound("Usuario no encontrado."));if(target.getId().equals(actor.id()))throw ApiException.conflict("No puedes suspender o reactivar tu propia cuenta.");if(request.action()==AdminUserAction.SUSPEND&&(request.reason()==null||request.reason().isBlank()))throw ApiException.badRequest("Debe indicar el motivo de la suspensión.");if(target.getRole()==UserRole.ADMIN&&request.action()==AdminUserAction.SUSPEND&&users.countByRoleAndAccountStatus(UserRole.ADMIN,AccountStatus.ACTIVE)<=1)throw ApiException.conflict("Debe permanecer al menos un administrador activo.");AccountStatus old=target.getAccountStatus(),next=request.action()==AdminUserAction.SUSPEND?AccountStatus.LOCKED:AccountStatus.ACTIVE;if(old==next)throw ApiException.conflict("La cuenta ya tiene ese estado.");target.setAccountStatus(next);users.save(target);String reason=request.reason()==null?null:request.reason().trim();audit.record(actor.user(),"USER_"+request.action(),"USER",id,old.name(),next.name(),reason);return AdminUserResponse.from(target);}
 private User find(UUID id){return users.findById(id).orElseThrow(()->ApiException.notFound("Usuario no encontrado."));}
}
